function annotationAt(event:Pick<MouseEvent,'clientX'|'clientY'>){if(!canvas.value)return undefined;const r=canvas.value.getBoundingClientRect(),point:[number,number]=[(event.clientX-r.left)*size.value[0]/r.width,(event.clientY-r.top)*size.value[1]/r.height];return imageAnnotations().reverse().find(item=>annotationLabelHit(item.layout,point));}
