function paintDensity(ctx:CanvasRenderingContext2D,kind:DensityROIKind,points:DensityROIPoints,plane:SlicePlane,color:string,label:string){const outline=densityROIOutline(kind,points,plane).map(screen);ctx.strokeStyle=color;ctx.fillStyle=color;ctx.lineWidth=1.5;ctx.beginPath();outline.forEach((point,index)=>index?ctx.lineTo(...point):ctx.moveTo(...point));ctx.closePath();ctx.stroke();for(const marker of densityROIMarkers(kind,points,plane)){const p=screen(marker.point);ctx.fillRect(p[0]-3,p[1]-3,6,6);}ctx.textAlign='left';ctx.font='12px Segoe UI,Microsoft YaHei';ctx.fillText(label,outline[0]![0]+9,outline[0]![1]-10);}
