function paintAffineDensity(ctx:CanvasRenderingContext2D){for(const item of imageAffineDensityROIs()){const {shape,m}=item,outline=shape.outline.map(worldScreen);ctx.strokeStyle=m.color;ctx.fillStyle=m.color;ctx.lineWidth=1.5;ctx.beginPath();outline.forEach((p,i)=>i?ctx.lineTo(...p):ctx.moveTo(...p));ctx.closePath();ctx.stroke();for(const marker of shape.markers){const p=worldScreen(marker.point);ctx.fillRect(p[0]-3,p[1]-3,6,6);}ctx.font='12px Segoe UI,Microsoft YaHei';ctx.textAlign='left';ctx.fillText((props.measurementLabels[m.id]||m.name)+(affineDensityPreview.value?.id===m.id?' · 松开更新':''),outline[0]![0]+9,outline[0]![1]-10);}}
function referenceSections(){if(!props.referenceLines?.length)return[];try{return resliceProjectReferenceLines(props.referenceLines,sourceSliceMprPlane(props.grid,props.axis,props.point[props.axis]));}catch{return[];}}
