function interactiveKey(){return JSON.stringify([props.interactivePlane,props.interactiveCenter,props.interactiveEnabled]);}
function interactiveOverlay(){if(!props.interactiveEnabled||!props.interactivePlane||!props.interactiveCenter)return null;try{const source=sourceSliceMprPlane(props.grid,props.axis,props.point[props.axis]),normal=mprPlaneNormal(source),projectScreen=(world:Vec3)=>{const distance=mprWorldToPixel(source,world).distance;return worldScreen(world.map((v,k)=>v-normal[k]*distance) as Vec3);},shown=interactivePreview.value??{plane:props.interactivePlane,crosshair:props.interactiveCenter},center=projectScreen(shown.crosshair),axes=interactiveMprAxes(shown.plane,source,shown.crosshair).map(axis=>{const end=projectScreen(shown.crosshair.map((v,k)=>v+axis.direction[k]) as Vec3),d:[number,number]=[end[0]-center[0],end[1]-center[1]],length=Math.hypot(...d);return{...axis,directionScreen:[d[0]/length,d[1]/length] as [number,number]};}).filter(axis=>axis.directionScreen.every(Number.isFinite));return{...shown,center,axes};}catch{return null;}}
function interactiveAt(event:Pick<MouseEvent,'clientX'|'clientY'>){if(!props.allowEdit)return null;const overlay=interactiveOverlay();if(!overlay)return null;const point=localScreen(event),delta=[point[0]-overlay.center[0],point[1]-overlay.center[1]];if(Math.hypot(...delta)<=8)return{action:'move' as const,cursor:'move'};for(const axis of overlay.axes)if(Math.abs(delta[0]*axis.directionScreen[1]-delta[1]*axis.directionScreen[0])<=6)return{action:'rotate' as const,cursor:'crosshair'};return null;}
function interactiveCurrent(){const d=interactiveDrag;return!!d&&props.allowEdit&&props.interactiveEnabled&&d.volume===props.volume&&d.grid===props.grid&&d.revision===props.revision&&d.mprRevision===(props.mprRevision??0)&&d.axis===props.axis&&d.slice===props.point[props.axis]&&d.key===interactiveKey();}
function controlKey(event:KeyboardEvent){if(event.key!=='Control')return;ctrlHeld.value=event.type!=='keyup';if(!ctrlHeld.value&&interactiveDrag)cancelPointer();schedule();}
function controlBlur(){ctrlHeld.value=false;if(interactiveDrag||affineDensityDrag)cancelPointer();schedule();}
function paintInteractive(ctx:CanvasRenderingContext2D){if(!ctrlHeld.value&&!interactiveDrag)return;const overlay=interactiveOverlay();if(!overlay)return;const reach=Math.hypot(...size.value)*2;ctx.save();ctx.strokeStyle='#45a6ff';ctx.fillStyle='#45a6ff';ctx.lineWidth=2;for(const axis of overlay.axes){const [x,y]=overlay.center,[dx,dy]=axis.directionScreen;ctx.beginPath();ctx.moveTo(x-dx*reach,y-dy*reach);ctx.lineTo(x+dx*reach,y+dy*reach);ctx.stroke();}ctx.beginPath();ctx.arc(...overlay.center,5,0,Math.PI*2);ctx.fill();ctx.font='11px Segoe UI,Microsoft YaHei';ctx.textAlign='left';ctx.fillText('Ctrl：拖蓝轴旋转，拖中心平移；松开提交',10,31);ctx.restore();}
function measurementSignature(m:MeasurementObject){return JSON.stringify([m.kind,m.points,m.partId??null,m.pointPartIds??null,m.plane??null,m.densityPlane??null,m.labelOffset??null,m.visible]);}
function editSnapshot(m:MeasurementObject):EditSnapshot{return{id:m.id,plane:{...m.plane!},volume:props.volume,grid:props.grid,revision:props.revision,signature:measurementSignature(m)};}
function snapshotCurrent(snapshot:EditSnapshot){const m=props.measurements.find(m=>m.id===snapshot.id);return props.allowEdit&&allowsMeasurementLabels(props.tool)&&snapshot.volume===props.volume&&snapshot.grid===props.grid&&snapshot.revision===props.revision&&snapshot.plane.axis===props.axis&&snapshot.plane.index===props.point[props.axis]&&!!m&&snapshot.signature===measurementSignature(m);}
function shownWorld(m:MeasurementObject){return shapePreview.value?.id===m.id?shapePreview.value.points:m.points.map((p,i)=>measurementDrag?.id===m.id&&measurementDrag.index===i?measurementDrag.position:p);}
function resultLines(kind:'area'|'ellipse',points:Vec3[]){const result=evaluateMeasurement(kind,points);if(!result.valid)return[`预览无效 · ${result.reason}`];const d=result.details,n=(key:string)=>typeof d[key]==='number'&&Number.isFinite(d[key])?Number(d[key]).toFixed(2):'—';return kind==='ellipse'?[`预览 · D1 ${n('D1')} mm · D2 ${n('D2')} mm · E ${n('E')}`,`P ${n('P')} mm · A ${n('A')} mm²`,`DP ${n('DP')} mm · DA ${n('DA')} mm`]:[`预览 · A ${result.value.toFixed(2)} mm² · P ${n('perimeter')} mm`,`Da ${n('Da')} mm · Dp ${n('Dp')} mm`,`Lmax ${n('Lmax')} mm · L ${n('L')} mm`];}
function ellipseOutline(points:Vec3[]){try{const f=ellipseFrame(points);return Array.from({length:128},(_,i)=>f.center.map((v,k)=>v+f.a*Math.cos(i*Math.PI/64)*f.u[k]+f.b*Math.sin(i*Math.PI/64)*f.v[k]) as Vec3);}catch{return[];}}
function imageMeasurements(){return props.measurements.filter(m=>m.visible&&m.kind!=='annotation'&&!isDensityROI(m.kind)&&m.plane?.axis===props.axis&&m.plane.index===props.point[props.axis]&&m.points.length).map(m=>{const world=shownWorld(m),shown={...m,points:world,...(labelPreview.value?.id===m.id?{labelOffset:labelPreview.value.offset}:{})},points=world.map(worldScreen);let handles:{id:string;kind:string;position:Vec3;point:[number,number]}[]=[];
  if(m.kind==='ellipse'){try{handles=ellipseHandles(world).map(handle=>({...handle,point:worldScreen(handle.position)}));}catch{/* Invalid local candidates retain their reason label. */}}else handles=world.map((position,index)=>({id:String(index),kind:'point',position,point:points[index]}));
  const preview=shapePreview.value?.id===m.id||measurementDrag?.id===m.id,lines=preview&&(m.kind==='area'||m.kind==='ellipse')?resultLines(m.kind,world):[props.measurementLabels[m.id]||m.name],labelPoint=worldScreen(measurementLabelPosition(shown)),label={x:labelPoint[0]+10,y:labelPoint[1]-10,width:Math.max(...lines.map(line=>Array.from(line).length))*7+8,height:lines.length*16};return{m,world,points,handles,lines,label,outline:m.kind==='ellipse'?ellipseOutline(world).map(worldScreen):points};});}
function shapeAt(event:Pick<MouseEvent,'clientX'|'clientY'>){if(!props.allowEdit||!allowsMeasurementLabels(props.tool))return undefined;const point=localScreen(event);for(const item of imageMeasurements().reverse()){if(item.m.kind!=='ellipse'&&item.m.kind!=='area')continue;const handle=item.handles.find(handle=>Math.hypot(handle.point[0]-point[0],handle.point[1]-point[1])<8);if(handle)return{...item,handle,labelHit:false};const {x,y,width,height}=item.label;if(point[0]>=x-4&&point[0]<=x+width&&point[1]>=y-13&&point[1]<=y-13+height)return{...item,labelHit:true,handle:undefined};}return undefined;}
function areaPointAt(event:Pick<MouseEvent,'clientX'|'clientY'>){if(!props.allowEdit||!allowsMeasurementLabels(props.tool))return undefined;const point=localScreen(event);for(const item of imageMeasurements().reverse()){if(item.m.kind!=='area')continue;const index=item.points.findIndex(p=>Math.hypot(p[0]-point[0],p[1]-point[1])<8);if(index>=0)return{measurement:item.m,index};}return undefined;}
function openAreaMenu(event:Pick<MouseEvent,'clientX'|'clientY'>){const hit=areaPointAt(event);areaMenu.value=null;if(!hit)return false;const {measurement:m,index}=hit,[x,y]=localScreen(event);areaMenu.value={...editSnapshot(m),index,x:Math.max(0,Math.min(size.value[0]-170,x)),y:Math.max(0,Math.min(size.value[1]-120,y)),points:m.points.map(p=>[...p] as Vec3)};return true;}
function editAreaPoint(action:'add'|'remove'){const menu=areaMenu.value;areaMenu.value=null;if(!menu||!snapshotCurrent(menu))return;const points=menu.points.map(p=>[...p] as Vec3);if(action==='remove'){if(points.length<=3){interactionError.value='Area 至少保留三个控制点。';return;}points.splice(menu.index,1);}else{const p=points[menu.index],q=points[(menu.index+1)%points.length];points.splice(menu.index+1,0,p.map((v,k)=>(v+q[k])/2) as Vec3);}const result=evaluateMeasurement('area',points);if(!result.valid){interactionError.value=result.reason??'Area 候选无效。';return;}emit('updateMeasurementGeometry',{id:menu.id,points,plane:menu.plane,volume:menu.volume,revision:menu.revision});schedule();}
function paintMeasurement(ctx:CanvasRenderingContext2D,item:ReturnType<typeof imageMeasurements>[number]){const {m,world,points,outline,handles,lines,label}=item;ctx.strokeStyle=m.color;ctx.fillStyle=m.color;ctx.lineWidth=1.5;ctx.beginPath();if(m.kind==='diameter'&&points.length===3){const result=evaluateMeasurement('diameter',world);if(result.valid)ctx.arc(...worldScreen(result.details.center as Vec3),Number(result.details.radius)*geometry.value.scale,0,Math.PI*2);}else{outline.forEach((p,i)=>i?ctx.lineTo(...p):ctx.moveTo(...p));if(m.kind==='area'||m.kind==='ellipse')ctx.closePath();}ctx.stroke();
