  if(kind==='affine-density'&&affine&&affinePreview&&affinePreview.points.some((p,i)=>Math.hypot(...p.map((v,k)=>v-affine.original[i]![k]!))>1e-8)){if(affineDensityROI(affine.kind,affinePreview.points,affine.densityPlane).hasArea)emit('updateMeasurementGeometry',{id:affine.id,points:affinePreview.points.map(p=>[...p]),densityPlane:validateAffinePlane(affine.densityPlane),plane:{...affine.plane},volume:affine.volume,revision:affine.revision});else interactionError.value='密度 ROI 宽高须大于零。';}
  if(kind==='interactive-mpr'&&blue&&bluePreview&&blue.moved&&!blue.invalid)emit('transformMpr',{plane:bluePreview.plane,crosshair:bluePreview.crosshair,sourcePlane:validateMprPlane(blue.sourcePlane),volume:blue.volume,revision:blue.revision,mprRevision:blue.mprRevision});
  if(kind==='density'&&roi&&roiDrag){if(!densityROIHasArea(roi.points,roi.plane))interactionError.value='密度 ROI 的宽高须大于零。';else if(roi.id){if(roiDrag.moved)emit('updateMeasurementGeometry',{id:roi.id,plane:{...roi.plane},points:roi.points.map(p=>physicalPoint(p,roiDrag.grid)),volume:roiDrag.volume,revision:roiDrag.revision});}else emit('createDensityROI',{kind:roi.kind,plane:{...roi.plane},points:roi.points.map(p=>[...p] as Vec3) as DensityROIPoints,volume:roiDrag.volume,revision:roiDrag.revision});}
  if(kind==='shape'&&shape&&geometryPreview&&shape.moved&&!shape.invalid){const result=evaluateMeasurement(shape.kind,geometryPreview.points);if(result.valid)emit('updateMeasurementGeometry',{id:shape.id,points:geometryPreview.points,plane:{...shape.plane},volume:shape.volume,revision:shape.revision});else interactionError.value=result.reason??'候选几何无效，未提交。';}
  if(kind==='label'&&label&&offset&&label.moved)emit('updateMeasurementLabel',{id:label.id,offset:offset.offset,plane:{...label.plane},volume:label.volume,revision:label.revision});
  if(kind==='resize'&&resized)emit('resizeBrush',resized);if(kind==='measurement'&&change)emit('moveMeasurementPoint',{id:change.id,index:change.index,position:[...change.position],plane:{...change.plane},volume:change.volume,revision:change.revision});if(kind==='brush')emit('end');if(kind==='lasso'){if(validContour)emit('complete');else emit('cancel');}schedule();
}
function cancelPointer(event?:PointerEvent){if(event&&gesture&&gesture.id!==event.pointerId)return;areaMenu.value=null;const editing=gesture?.kind==='brush'||gesture?.kind==='lasso';clearGesture();if(editing)emit('cancel');schedule();}
function key(event:KeyboardEvent){if(event.key==='Escape')cancelPointer();}
function leave(){if(gesture?.kind!=='resize')cursor.value=null;annotationHover.value='';schedule();}
function doubleClick(event:MouseEvent){if(event.shiftKey||event.ctrlKey&&(brush.value||props.interactiveEnabled))return;const hit=allowsMeasurementLabels(props.tool)?annotationAt(event):undefined;if(hit){event.preventDefault?.();event.stopPropagation?.();if(props.allowEdit)emit('editMeasurement',hit.id);return;}if(shapeAt(event)){event.preventDefault?.();return;}emit('complete');}
function slice(value:number){cancelPointer();const p=[...props.point] as Vec3;p[props.axis]=Math.max(0,Math.min(props.volume.dims[props.axis]-1,Math.round(value)));emit('point',p);}
function wheel(event:WheelEvent){cancelPointer();if(event.ctrlKey||event.shiftKey){const p=locate(event);zoom.value=Math.max(.15,Math.min(12,zoom.value*Math.exp(-event.deltaY*.002)));if(p&&canvas.value){const r=canvas.value.getBoundingClientRect(),s=screen(p);pan.value=[pan.value[0]+(event.clientX-r.left)*size.value[0]/r.width-s[0],pan.value[1]+(event.clientY-r.top)*size.value[1]/r.height-s[1]];}cursor.value=locate(event);}else if(event.deltaY)slice(props.point[props.axis]+Math.sign(event.deltaY));schedule();}
watch(()=>[props.revision,props.draftRevision,props.point,props.center,props.width,props.preview,props.temporarySelection,props.previewReplacesActive,props.displayInverted,props.draft,props.masks,props.measurements,props.measurementLabels,props.draftPoints,props.draftPlane,props.diameter,props.brushWidth,props.brushHeight,props.sameWidthHeight,props.brushShape,props.referenceLines,zoom.value,pan.value],schedule,{deep:false});
watch([()=>props.tool,()=>props.activeMaskId,()=>props.axis,()=>props.point[props.axis],()=>props.allowEdit,()=>props.grid,()=>props.diameter,()=>props.brushWidth,()=>props.brushHeight,()=>props.sameWidthHeight,()=>props.brushShape,()=>props.densitySize?.[0],()=>props.densitySize?.[1]],()=>cancelPointer(),{flush:'sync'});
watch([()=>props.measurements,()=>props.point[props.axis]],()=>{annotationHover.value='';if(densityDrag||measurementDrag||shapeDrag||labelDrag||interactiveDrag||areaMenu.value)cancelPointer();},{flush:'sync'});
watch(()=>props.revision,()=>{if(densityDrag||measurementDrag||shapeDrag||labelDrag||interactiveDrag||areaMenu.value)cancelPointer();},{flush:'sync'});
watch(()=>props.volume,()=>{cancelPointer();zoom.value=1;pan.value=[0,0];cursor.value=null;schedule();},{flush:'sync'});
watch([interactiveKey,()=>props.mprRevision],()=>{if(interactiveDrag)cancelPointer();schedule();},{flush:'sync'});
watch([()=>props.volume,()=>props.revision,()=>props.mprRevision,()=>props.measurements,()=>JSON.stringify(props.measurements.filter(m=>m.densityPlane).map(m=>[m.id,measurementSignature(m)]))],()=>{if(affineDensityDrag&&!affineDensityCurrent(affineDensityDrag))cancelPointer();},{flush:'sync'});
onMounted(()=>{observer=new ResizeObserver(entries=>{if(interactiveDrag||affineDensityDrag)cancelPointer();size.value=[Math.max(1,entries[0].contentRect.width),Math.max(1,entries[0].contentRect.height)];schedule();});observer.observe(host.value!);window.addEventListener('keydown',key);window.addEventListener('keydown',controlKey);window.addEventListener('keyup',controlKey);window.addEventListener('blur',controlBlur);schedule();});
onBeforeUnmount(()=>{cancelPointer();observer?.disconnect();cancelAnimationFrame(frame);window.removeEventListener('keydown',key);window.removeEventListener('keydown',controlKey);window.removeEventListener('keyup',controlKey);window.removeEventListener('blur',controlBlur);});
</script>
<template>
  <section class="image-viewport" :data-axis="axis" :data-slice-space="rawSlice?'ijk':'axis-aligned'" :data-spatial-unit="volume.unit">
    <header :title="rawSlice?'按 affine 显示原始 IJK 切片，保留倾斜/剪切几何；未经标准 MPR 重采样。':''"><b :style="{color:['#eab365','#72cba8','#7fb2f3'][axis]}">{{sliceLabel}}</b><span>{{point[axis]+1}} / {{volume.dims[axis]}}</span><button title="重置缩放和平移" @click="cancelPointer();zoom=1;pan=[0,0];cursor=null">适配</button></header>
    <div ref="host" class="canvas-host"><canvas ref="canvas" tabindex="0" :title="annotationHover" :style="{cursor:densityCursor}" :aria-label="`${sliceLabel}，滚轮切片，Shift左键定位，Ctrl滚轮缩放，Ctrl左键拖动调整笔刷，右键平移；右击Area点增删；椭圆四轴端缩放、中心平移、角点旋转、标签拖放`" @pointerdown="down" @pointermove="move" @pointerup="end" @pointercancel="cancelPointer" @lostpointercapture="cancelPointer" @pointerleave="leave" @contextmenu.prevent="!gesture&&openAreaMenu($event)" @dblclick="doubleClick" @wheel.prevent="wheel"/><div v-if="areaMenu" class="area-point-menu" role="menu" aria-label="Area 控制点" :style="{left:`${areaMenu.x}px`,top:`${areaMenu.y}px`}" @pointerdown.stop @contextmenu.prevent><button role="menuitem" @click="editAreaPoint('add')">Add Point · 添加点</button><button role="menuitem" :disabled="areaMenu.points.length<=3" @click="editAreaPoint('remove')">Remove Point · 删除点</button><small>添加到下一条边的中点，可再拖动；至少保留三点。</small></div><div v-if="interactionError" class="viewport-error" role="alert">{{interactionError}}</div></div>
    <footer><input :aria-label="`${sliceLabel}切片`" type="range" min="0" :max="volume.dims[axis]-1" :value="point[axis]" @input="slice(Number(($event.target as HTMLInputElement).value))"><span :title="cursor?`IJK ${cursor.map(v=>v.toFixed(2)).join(', ')} · ${physicalPoint(cursor,grid).map(v=>v.toFixed(2)).join(', ')} ${volume.unit}`:''">{{cursor?volume.data[indexOf(cursor.map(Math.round),volume.dims)].toFixed(1):'—'}} {{intensityUnit||''}}</span></footer>
    <slot v-if="$slots?.['annotation-hover']" name="annotation-hover" :zoom="zoom" :zoom-wheel="wheel" :locate="locate" :grid="grid" :volume="volume" :axis="axis" :point="point" :view="geometry" :size="size" :revision="revision"/>
  </section>
</template>
<style scoped>
.image-viewport{min-width:0;min-height:0;display:flex;flex-direction:column;background:#060b14;border:1px solid #26334a;border-radius:7px;overflow:hidden}.image-viewport header{display:flex;align-items:center;padding:7px 11px;gap:14px;background:#111d2e;font-size:12px;color:#94a8c3}.image-viewport header b{font-weight:600}.image-viewport header button{margin-left:auto;background:transparent;border:1px solid #32445d;border-radius:4px;color:#adbed4;padding:2px 7px;font:inherit;cursor:pointer}.canvas-host{flex:1;min-height:100px;position:relative}.canvas-host canvas{width:100%;height:100%;display:block;touch-action:none}.image-viewport footer{display:flex;align-items:center;gap:9px;padding:5px 9px;background:#101b2c;height:28px}.image-viewport input{width:100%;height:4px;accent-color:#6ca8e8}.image-viewport footer span{min-width:48px;text-align:right;font:11px Consolas;color:#9baec7}
.viewport-error{position:absolute;left:10px;right:10px;bottom:10px;padding:7px 9px;background:#48252de8;color:#ffd2c7;border:1px solid #9a5b62;border-radius:4px;font-size:11px;pointer-events:none}
.area-point-menu{position:absolute;box-sizing:border-box;width:170px;padding:5px;background:#14263ced;border:1px solid #56789d;border-radius:5px;box-shadow:0 5px 15px #0008;z-index:3}.area-point-menu button{display:block;width:100%;padding:6px;border:0;background:transparent;color:#d6e7f7;text-align:left;font:11px Segoe UI,Microsoft YaHei;cursor:pointer}.area-point-menu button:hover{background:#294762}.area-point-menu button:disabled{opacity:.4;cursor:default}.area-point-menu small{display:block;padding:5px;color:#93adc9;font:10px/1.6 Segoe UI,Microsoft YaHei}
